class Provider implements CustomSource {
    // No API key needed.
    // Used only as a fallback. Direct YouTube search is tried first.
    invidious_instance = "https://inv.nadeko.net"

    region_code = "CA"

    getSettings(): Settings {
        return {
            supportsAnime: true,
            supportsManga: false,
        }
    }

    async getAnime(ids: number[]): Promise<$app.AL_BaseAnime[]> {
        const ret: $app.AL_BaseAnime[] = []
        const cache = this._getMediaCache()

        for (const id of ids) {
            const cached = cache[id]
            if (cached?.media) {
                ret.push(cached.media)
            }
        }

        return ret
    }

    async getAnimeDetails(id: number): Promise<$app.AL_AnimeDetailsById_Media | null> {
        return null
    }

    async getAnimeMetadata(id: number): Promise<$app.Metadata_AnimeMetadata | null> {
        const cache = this._getMediaCache()
        return cache[id]?.metadata ?? null
    }

    async getAnimeWithRelations(id: number): Promise<$app.AL_CompleteAnime> {
        const cache = this._getMediaCache()
        const cached = cache[id]

        if (!cached?.media) {
            throw new Error("not found.")
        }

        return {
            ...(cached.media as any),
            relations: { edges: [] },
        } as $app.AL_CompleteAnime
    }

    async listAnime(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseAnime>> {
        const query = String(search || "").trim()
        const currentPage = page && page > 0 ? page : 1
        const limit = Math.max(1, Math.min(perPage || 20, 50))

        let videos: InvidiousVideo[] = []

        if (query.length > 0) {
            const videoId = this._getYouTubeId(query)

            if (videoId) {
                const single = await this._getVideo(videoId)
                videos = single ? [single] : []
            } else {
                videos = await this._searchEverywhere(query, currentPage)
            }
        } else {
            videos = await this._getPopularVideos()
        }

        videos = this._dedupeVideos(videos)
            .filter(v => v && v.videoId)
            .filter(v => !v.paid && !v.premium)
            .slice(0, limit)

        const cache = this._getMediaCache()
        const media: $app.AL_BaseAnime[] = []

        for (const video of videos) {
            const stored = this._videoToStoredMedia(video)
            cache[stored.media.id] = stored
            media.push(stored.media)
        }

        this._setMediaCache(cache)

        return {
            media,
            total: query.length > 0 ? Math.max(media.length, currentPage * limit + media.length) : media.length,
            page: currentPage,
            totalPages: query.length > 0 && media.length >= limit ? currentPage + 1 : Math.max(1, currentPage),
        }
    }

    async getManga(ids: number[]): Promise<$app.AL_BaseManga[]> {
        return []
    }

    async getMangaDetails(id: number): Promise<$app.AL_MangaDetailsById_Media | null> {
        return null
    }

    async listManga(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseManga>> {
        return {
            media: [],
            total: 0,
            page: 1,
            totalPages: 1,
        }
    }

    private async _searchEverywhere(query: string, page: number): Promise<InvidiousVideo[]> {
        console.log("YouTube source search:", query)

        const directYoutube = await this._searchYouTubeHtml(query)

        if (directYoutube.length > 0) {
            console.log("YouTube direct search results:", directYoutube.length)
            return directYoutube
        }

        const invidious = await this._searchInvidious(query, page)

        if (invidious.length > 0) {
            console.log("Invidious search results:", invidious.length)
            return invidious
        }

        const piped = await this._searchPiped(query)

        if (piped.length > 0) {
            console.log("Piped search results:", piped.length)
            return piped
        }

        console.error("All YouTube search methods returned nothing.")
        return []
    }

    private async _searchYouTubeHtml(query: string): Promise<InvidiousVideo[]> {
        const urls = [
            `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}&sp=EgIQAQ%253D%253D`,
            `https://m.youtube.com/results?search_query=${encodeURIComponent(query)}`,
        ]

        for (const url of urls) {
            try {
                const html = await this._fetchText(url)

                if (!html || html.length < 1000) {
                    continue
                }

                const renderers = this._extractJsonObjects(html, "videoRenderer")
                const videos: InvidiousVideo[] = []

                for (const renderer of renderers) {
                    const video = this._youtubeRendererToVideo(renderer)
                    if (video) {
                        videos.push(video)
                    }
                }

                const deduped = this._dedupeVideos(videos)

                if (deduped.length > 0) {
                    return deduped
                }
            } catch (err) {
                console.error("Direct YouTube search failed:", err)
            }
        }

        return []
    }

    private async _searchInvidious(query: string, page: number): Promise<InvidiousVideo[]> {
        const instances = this._uniqueStrings([
            this._instance(),
            "https://inv.nadeko.net",
            "https://yewtu.be",
            "https://invidious.privacyredirect.com",
            "https://iv.ggtyler.dev",
            "https://inv.tux.pizza",
            "https://invidious.nerdvpn.de",
        ])

        for (const instanceRaw of instances) {
            const instance = this._trimSlash(instanceRaw)

            const urls = [
                `${instance}/api/v1/search?q=${encodeURIComponent(query)}&page=${encodeURIComponent(String(page || 1))}&type=video&sort_by=relevance&region=${encodeURIComponent(this.region_code || "CA")}`,
                `${instance}/api/v1/search?q=${encodeURIComponent(query)}&page=${encodeURIComponent(String(page || 1))}&type=video&sort=relevance&region=${encodeURIComponent(this.region_code || "CA")}`,
                `${instance}/api/v1/search?q=${encodeURIComponent(query)}&page=${encodeURIComponent(String(page || 1))}&type=video`,
            ]

            for (const url of urls) {
                try {
                    console.log("Trying Invidious search:", url)

                    const data = await this._fetchJson<any>(url)

                    if (!Array.isArray(data)) {
                        continue
                    }

                    const videos: InvidiousVideo[] = []

                    for (const item of data) {
                        const normalized = this._normalizeInvidiousSearchItem(item)
                        if (normalized) {
                            videos.push(normalized)
                        }
                    }

                    const deduped = this._dedupeVideos(videos)

                    if (deduped.length > 0) {
                        return deduped
                    }
                } catch (err) {
                    console.error("Invidious search error:", instance, err)
                }
            }
        }

        return []
    }

    private async _searchPiped(query: string): Promise<InvidiousVideo[]> {
        const instances = [
            "https://pipedapi.kavin.rocks",
            "https://pipedapi.adminforge.de",
            "https://pipedapi.syncpundit.io",
            "https://pipedapi-libre.kavin.rocks",
        ]

        for (const instanceRaw of instances) {
            const instance = this._trimSlash(instanceRaw)
            const url = `${instance}/search?filter=videos&q=${encodeURIComponent(query)}`

            try {
                console.log("Trying Piped search:", url)

                const data = await this._fetchJson<any>(url)
                const arr = Array.isArray(data) ? data : Array.isArray(data?.items) ? data.items : []

                if (!Array.isArray(arr)) {
                    continue
                }

                const videos: InvidiousVideo[] = []

                for (const item of arr) {
                    const normalized = this._normalizePipedSearchItem(item)
                    if (normalized) {
                        videos.push(normalized)
                    }
                }

                const deduped = this._dedupeVideos(videos)

                if (deduped.length > 0) {
                    return deduped
                }
            } catch (err) {
                console.error("Piped search error:", instance, err)
            }
        }

        return []
    }

    private async _getPopularVideos(): Promise<InvidiousVideo[]> {
        const instances = this._uniqueStrings([
            this._instance(),
            "https://inv.nadeko.net",
            "https://yewtu.be",
            "https://invidious.privacyredirect.com",
            "https://iv.ggtyler.dev",
            "https://inv.tux.pizza",
            "https://invidious.nerdvpn.de",
        ])

        for (const instanceRaw of instances) {
            const instance = this._trimSlash(instanceRaw)

            const urls = [
                `${instance}/api/v1/popular`,
                `${instance}/api/v1/trending?region=${encodeURIComponent(this.region_code || "CA")}`,
            ]

            for (const url of urls) {
                try {
                    const data = await this._fetchJson<any>(url)

                    if (!Array.isArray(data)) {
                        continue
                    }

                    const videos: InvidiousVideo[] = []

                    for (const item of data) {
                        const normalized = this._normalizeInvidiousSearchItem(item)
                        if (normalized) {
                            videos.push(normalized)
                        }
                    }

                    const deduped = this._dedupeVideos(videos)

                    if (deduped.length > 0) {
                        return deduped
                    }
                } catch (err) {
                    console.error("Invidious popular/trending error:", instance, err)
                }
            }
        }

        return []
    }

    private async _getVideo(videoId: string): Promise<InvidiousVideo | null> {
        const instances = this._uniqueStrings([
            this._instance(),
            "https://inv.nadeko.net",
            "https://yewtu.be",
            "https://invidious.privacyredirect.com",
            "https://iv.ggtyler.dev",
            "https://inv.tux.pizza",
            "https://invidious.nerdvpn.de",
        ])

        for (const instanceRaw of instances) {
            const instance = this._trimSlash(instanceRaw)
            const url = `${instance}/api/v1/videos/${encodeURIComponent(videoId)}?region=${encodeURIComponent(this.region_code || "CA")}`

            try {
                const data = await this._fetchJson<any>(url)

                const normalized = this._normalizeInvidiousSearchItem(data)

                if (normalized) {
                    return normalized
                }
            } catch (err) {
                console.error("Invidious video error:", instance, err)
            }
        }

        const oembed = await this._getVideoFromOEmbed(videoId)

        if (oembed) {
            return oembed
        }

        return {
            type: "video",
            title: `YouTube Video ${videoId}`,
            videoId,
            author: "YouTube",
            videoThumbnails: this._fallbackThumbnails(videoId),
            description: "",
            viewCount: 0,
            publishedText: "",
            lengthSeconds: 0,
        }
    }

    private async _getVideoFromOEmbed(videoId: string): Promise<InvidiousVideo | null> {
        const url = `https://www.youtube.com/oembed?url=${encodeURIComponent(`https://www.youtube.com/watch?v=${videoId}`)}&format=json`

        try {
            const data = await this._fetchJson<any>(url)

            if (!data || !data.title) {
                return null
            }

            return {
                type: "video",
                title: data.title || "YouTube Video",
                videoId,
                author: data.author_name || "YouTube",
                authorUrl: data.author_url || "",
                videoThumbnails: data.thumbnail_url ? [{ url: data.thumbnail_url }] : this._fallbackThumbnails(videoId),
                description: "",
                viewCount: 0,
                publishedText: "",
                lengthSeconds: 0,
            }
        } catch (err) {
            console.error("YouTube oEmbed failed:", err)
            return null
        }
    }

    private _videoToStoredMedia(video: InvidiousVideo): StoredYoutubeMedia {
        const videoId = video.videoId
        const id = this._numericId(videoId)

        const title = this._decode(video.title || "YouTube Video")
        const author = this._decode(video.author || "YouTube")
        const thumb = this._bestThumbnail(video.videoThumbnails || this._fallbackThumbnails(videoId))

        const publishedDate = this._publishedToDate(video.published)
        const airDate = publishedDate
            ? `${publishedDate.year}-${this._pad(publishedDate.month || 1)}-${this._pad(publishedDate.day || 1)}`
            : ""

        const lengthMinutes = video.lengthSeconds
            ? Math.max(1, Math.round(video.lengthSeconds / 60))
            : 0

        const views = typeof video.viewCount === "number" && video.viewCount > 0
            ? `${this._formatNumber(video.viewCount)} views`
            : ""

        const description = this._truncate(
            [
                `Channel: ${author}`,
                views,
                video.publishedText || "",
                "",
                this._decode(video.description || ""),
                "",
                `Watch on YouTube: https://www.youtube.com/watch?v=${videoId}`,
            ].filter(Boolean).join("\n"),
            4500,
        )

        const media: $app.AL_BaseAnime = {
            id,
            siteUrl: `https://www.youtube.com/watch?v=${videoId}`,
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: title,
            },
            coverImage: {
                large: thumb,
                medium: thumb,
                extraLarge: thumb,
                color: "",
            },
            bannerImage: thumb,
            description,
            genres: ["YouTube", author],
            meanScore: 0,
            synonyms: [videoId, author],
            status: "FINISHED",
            episodes: 1,
            type: "ANIME",
            format: "ONA",
            seasonYear: publishedDate?.year || new Date().getUTCFullYear(),
            isAdult: false,
            startDate: publishedDate || {
                year: new Date().getUTCFullYear(),
            },
            endDate: publishedDate || undefined,
        }

        const metadata: $app.Metadata_AnimeMetadata = {
            titles: {
                en: title,
            },
            episodes: {
                "1": {
                    anidbId: 0,
                    tvdbId: 0,
                    anidbEid: 0,
                    title,
                    image: thumb,
                    airDate,
                    length: lengthMinutes,
                    summary: description,
                    overview: description,
                    episodeNumber: 1,
                    episode: "1",
                    seasonNumber: 1,
                    absoluteEpisodeNumber: 1,
                    hasImage: !!thumb,
                },
            },
            episodeCount: 1,
            specialCount: 0,
        }

        return {
            videoId,
            media,
            metadata,
        }
    }

    private _normalizeInvidiousSearchItem(item: any): InvidiousVideo | null {
        if (!item) return null

        const videoId = item.videoId || this._getYouTubeId(item.url || item.link || "")

        if (!videoId) {
            return null
        }

        const type = item.type || "video"

        if (type !== "video" && type !== "stream") {
            return null
        }

        return {
            type: "video",
            title: item.title || "YouTube Video",
            videoId,
            author: item.author || item.authorName || item.uploaderName || "YouTube",
            authorId: item.authorId || "",
            authorUrl: item.authorUrl || "",
            videoThumbnails: Array.isArray(item.videoThumbnails)
                ? item.videoThumbnails
                : Array.isArray(item.thumbnails)
                    ? item.thumbnails
                    : item.thumbnail
                        ? [{ url: item.thumbnail }]
                        : this._fallbackThumbnails(videoId),
            description: item.description || item.descriptionHtml || "",
            viewCount: typeof item.viewCount === "number" ? item.viewCount : this._parseViewCount(item.viewCountText || item.shortViewCountText || ""),
            published: typeof item.published === "number" ? item.published : undefined,
            publishedText: item.publishedText || item.publishedTimeText || item.uploadedDate || "",
            lengthSeconds: typeof item.lengthSeconds === "number"
                ? item.lengthSeconds
                : this._parseDurationText(item.lengthText || item.duration || ""),
            liveNow: !!item.liveNow,
            paid: !!item.paid,
            premium: !!item.premium,
        }
    }

    private _normalizePipedSearchItem(item: any): InvidiousVideo | null {
        if (!item) return null

        const type = item.type || ""

        if (type && type !== "stream" && type !== "video") {
            return null
        }

        const videoId = this._getYouTubeId(item.url || item.link || item.id || item.videoId || "")

        if (!videoId) {
            return null
        }

        return {
            type: "video",
            title: item.title || "YouTube Video",
            videoId,
            author: item.uploaderName || item.author || item.uploader || "YouTube",
            authorUrl: item.uploaderUrl || "",
            videoThumbnails: item.thumbnail ? [{ url: item.thumbnail }] : this._fallbackThumbnails(videoId),
            description: item.description || "",
            viewCount: typeof item.views === "number" ? item.views : this._parseViewCount(item.views || item.viewCount || ""),
            publishedText: item.uploadedDate || item.uploadedDateText || "",
            lengthSeconds: typeof item.duration === "number" ? item.duration : this._parseDurationText(item.duration || ""),
            liveNow: !!item.isLive,
            paid: false,
            premium: false,
        }
    }

    private _youtubeRendererToVideo(renderer: any): InvidiousVideo | null {
        if (!renderer || !renderer.videoId) {
            return null
        }

        const videoId = renderer.videoId
        const title = this._textFromRuns(renderer.title) || "YouTube Video"

        const author =
            this._textFromRuns(renderer.ownerText) ||
            this._textFromRuns(renderer.shortBylineText) ||
            this._textFromRuns(renderer.longBylineText) ||
            "YouTube"

        const description =
            this._textFromRuns(renderer.detailedMetadataSnippets?.[0]?.snippetText) ||
            this._textFromRuns(renderer.descriptionSnippet) ||
            ""

        const publishedText = this._textFromRuns(renderer.publishedTimeText) || ""
        const viewText = this._textFromRuns(renderer.viewCountText) || this._textFromRuns(renderer.shortViewCountText) || ""
        const lengthText = this._textFromRuns(renderer.lengthText) || renderer.lengthText?.accessibility?.accessibilityData?.label || ""

        const rawThumbs = renderer.thumbnail?.thumbnails || []
        const videoThumbnails: InvidiousThumbnail[] = []

        if (Array.isArray(rawThumbs)) {
            for (const thumb of rawThumbs) {
                if (thumb?.url) {
                    videoThumbnails.push({
                        url: thumb.url,
                        width: thumb.width,
                        height: thumb.height,
                    })
                }
            }
        }

        return {
            type: "video",
            title,
            videoId,
            author,
            videoThumbnails: videoThumbnails.length > 0 ? videoThumbnails : this._fallbackThumbnails(videoId),
            description,
            viewCount: this._parseViewCount(viewText),
            publishedText,
            lengthSeconds: this._parseDurationText(lengthText),
            liveNow: !!renderer.badges?.some((b: any) => this._textFromRuns(b?.metadataBadgeRenderer?.label).toLowerCase().includes("live")),
            paid: false,
            premium: false,
        }
    }

    private async _fetchText(url: string): Promise<string> {
        try {
            const res = await fetch(url, {
                headers: {
                    "Accept": "text/html,application/json",
                    "Accept-Language": "en-US,en;q=0.9",
                },
            })

            if (!res.ok) {
                throw new Error(`HTTP ${res.status}`)
            }

            return await res.text()
        } catch (err) {
            const res = await fetch(url)

            if (!res.ok) {
                throw new Error(`HTTP ${res.status}`)
            }

            return await res.text()
        }
    }

    private async _fetchJson<T>(url: string): Promise<T | null> {
        const text = await this._fetchText(url)

        if (!text || text.trim().startsWith("<")) {
            return null
        }

        return JSON.parse(text) as T
    }

    private _extractJsonObjects(text: string, key: string): any[] {
        const results: any[] = []
        const needle = `"${key}":`
        let pos = 0

        while (true) {
            const idx = text.indexOf(needle, pos)

            if (idx < 0) {
                break
            }

            const start = text.indexOf("{", idx + needle.length)

            if (start < 0) {
                break
            }

            const raw = this._readBalancedObject(text, start)

            if (!raw) {
                pos = idx + needle.length
                continue
            }

            try {
                results.push(JSON.parse(raw))
            } catch (err) {
            }

            pos = start + raw.length
        }

        return results
    }

    private _readBalancedObject(text: string, start: number): string {
        let depth = 0
        let inString = false
        let escape = false

        for (let i = start; i < text.length; i++) {
            const ch = text[i]

            if (inString) {
                if (escape) {
                    escape = false
                } else if (ch === "\\") {
                    escape = true
                } else if (ch === "\"") {
                    inString = false
                }

                continue
            }

            if (ch === "\"") {
                inString = true
                continue
            }

            if (ch === "{") {
                depth++
            } else if (ch === "}") {
                depth--

                if (depth === 0) {
                    return text.slice(start, i + 1)
                }
            }
        }

        return ""
    }

    private _textFromRuns(obj: any): string {
        if (!obj) return ""

        if (typeof obj === "string") {
            return obj
        }

        if (typeof obj.simpleText === "string") {
            return obj.simpleText
        }

        if (typeof obj.label === "string") {
            return obj.label
        }

        if (Array.isArray(obj.runs)) {
            let out = ""

            for (const run of obj.runs) {
                if (typeof run?.text === "string") {
                    out += run.text
                }
            }

            return out
        }

        if (obj.accessibility?.accessibilityData?.label) {
            return obj.accessibility.accessibilityData.label
        }

        return ""
    }

    private _getYouTubeId(input: string): string {
        const trimmed = String(input || "").trim()

        const patterns = [
            /(?:youtube\.com\/watch\?v=)([a-zA-Z0-9_-]{6,})/,
            /(?:youtube\.com\/watch\?.*?&v=)([a-zA-Z0-9_-]{6,})/,
            /(?:youtu\.be\/)([a-zA-Z0-9_-]{6,})/,
            /(?:youtube\.com\/embed\/)([a-zA-Z0-9_-]{6,})/,
            /(?:youtube\.com\/shorts\/)([a-zA-Z0-9_-]{6,})/,
            /(?:\/watch\?v=)([a-zA-Z0-9_-]{6,})/,
        ]

        for (const pattern of patterns) {
            const match = trimmed.match(pattern)
            if (match?.[1]) return match[1]
        }

        if (/^[a-zA-Z0-9_-]{11}$/.test(trimmed)) {
            return trimmed
        }

        return ""
    }

    private _bestThumbnail(thumbnails: InvidiousThumbnail[]): string {
        if (!Array.isArray(thumbnails) || thumbnails.length === 0) return ""

        const sorted = thumbnails
            .slice()
            .filter(t => !!t?.url)
            .sort((a, b) => ((b.width || 0) * (b.height || 0)) - ((a.width || 0) * (a.height || 0)))

        if (sorted.length === 0) {
            return ""
        }

        return this._normalizeUrl(sorted[0].url)
    }

    private _fallbackThumbnails(videoId: string): InvidiousThumbnail[] {
        return [
            {
                quality: "maxres",
                url: `https://i.ytimg.com/vi/${videoId}/maxresdefault.jpg`,
                width: 1280,
                height: 720,
            },
            {
                quality: "high",
                url: `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`,
                width: 480,
                height: 360,
            },
        ]
    }

    private _normalizeUrl(url: string): string {
        if (!url) return ""

        if (url.startsWith("//")) {
            return "https:" + url
        }

        if (url.startsWith("/")) {
            return this._instance() + url
        }

        return url
    }

    private _publishedToDate(published?: number): { year: number, month?: number, day?: number } | null {
        if (!published || typeof published !== "number") {
            return null
        }

        const d = new Date(published * 1000)

        if (isNaN(d.getTime())) {
            return null
        }

        return {
            year: d.getUTCFullYear(),
            month: d.getUTCMonth() + 1,
            day: d.getUTCDate(),
        }
    }

    private _numericId(videoId: string): number {
        let hash = 2166136261

        for (let i = 0; i < videoId.length; i++) {
            hash ^= videoId.charCodeAt(i)
            hash = Math.imul(hash, 16777619)
        }

        return Math.abs(hash) + 1
    }

    private _parseViewCount(input: any): number {
        const text = String(input || "").replace(/,/g, "").trim()

        if (!text) return 0

        const match = text.match(/([\d.]+)\s*([KMB])?/i)

        if (!match) return 0

        const base = Number(match[1])

        if (isNaN(base)) return 0

        const suffix = String(match[2] || "").toUpperCase()

        if (suffix === "B") return Math.round(base * 1000000000)
        if (suffix === "M") return Math.round(base * 1000000)
        if (suffix === "K") return Math.round(base * 1000)

        return Math.round(base)
    }

    private _parseDurationText(input: any): number {
        const text = String(input || "").trim()

        if (!text) return 0

        if (/^\d+$/.test(text)) {
            return Number(text)
        }

        const clean = text
            .replace(/hours?/gi, ":")
            .replace(/minutes?/gi, ":")
            .replace(/seconds?/gi, "")
            .replace(/\s+/g, "")
            .replace(/:+$/g, "")

        const parts = clean.split(":")
            .map(p => Number(p))
            .filter(n => !isNaN(n))

        if (parts.length === 0) return 0

        let seconds = 0

        for (const part of parts) {
            seconds = seconds * 60 + part
        }

        return seconds
    }

    private _instance(): string {
        let instance = this.invidious_instance || "https://inv.nadeko.net"

        if (instance.includes("{{") || instance.includes("}}")) {
            instance = "https://inv.nadeko.net"
        }

        return this._trimSlash(instance)
    }

    private _trimSlash(input: string): string {
        let value = String(input || "").trim()

        while (value.endsWith("/")) {
            value = value.slice(0, -1)
        }

        return value
    }

    private _uniqueStrings(items: string[]): string[] {
        const seen: Record<string, boolean> = {}
        const ret: string[] = []

        for (const item of items) {
            const clean = this._trimSlash(item)

            if (!clean || seen[clean]) {
                continue
            }

            seen[clean] = true
            ret.push(clean)
        }

        return ret
    }

    private _dedupeVideos(videos: InvidiousVideo[]): InvidiousVideo[] {
        const seen: Record<string, boolean> = {}
        const ret: InvidiousVideo[] = []

        for (const video of videos) {
            if (!video?.videoId || seen[video.videoId]) {
                continue
            }

            seen[video.videoId] = true
            ret.push(video)
        }

        return ret
    }

    private _decode(input: string): string {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
    }

    private _truncate(input: string, max: number): string {
        if (!input) return ""
        if (input.length <= max) return input
        return input.slice(0, max - 3) + "..."
    }

    private _formatNumber(value: number): string {
        if (!value || isNaN(value)) return "0"

        if (value >= 1000000000) return `${Math.round(value / 100000000) / 10}B`
        if (value >= 1000000) return `${Math.round(value / 100000) / 10}M`
        if (value >= 1000) return `${Math.round(value / 100) / 10}K`

        return value.toString()
    }

    private _pad(value: number): string {
        return value < 10 ? `0${value}` : `${value}`
    }

    private _getMediaCache(): Record<number, StoredYoutubeMedia> {
        return ($store.get("youtube.media") as Record<number, StoredYoutubeMedia> | undefined) || {}
    }

    private _setMediaCache(cache: Record<number, StoredYoutubeMedia>) {
        $store.set("youtube.media", cache)
    }
}

